// Corre una vez al día (cron diario, como pidió Marco) — por eso los
// umbrales de 72/24/6hs son aproximados, no exactos: si la corrida de hoy
// encuentra que ya faltan menos de 24hs y todavía no se avisó ni el tramo
// de 72hs, se manda directo el aviso de 24hs (el más urgente sin avisar) y
// se marcan como "avisados" todos los tramos ya cruzados, para no mandar
// después un aviso de 72hs desactualizado.
const filas = $input.all().map((i) => i.json);
const ahora = Date.now();
const alertas = [];

for (const fila of filas) {
  const postulado = String(fila.postulado).toLowerCase() === 'true';
  if (!postulado || !fila.obligacion_fecha) continue;

  const fechaObligacion = new Date(fila.obligacion_fecha);
  if (isNaN(fechaObligacion.getTime())) continue;

  const horasRestantes = (fechaObligacion.getTime() - ahora) / 1000 / 60 / 60;

  const avisado72 = String(fila.avisado_72h).toLowerCase() === 'true';
  const avisado24 = String(fila.avisado_24h).toLowerCase() === 'true';
  const avisado6 = String(fila.avisado_6h).toLowerCase() === 'true';

  let tier = null;
  if (horasRestantes <= 6 && !avisado6) tier = '6';
  else if (horasRestantes <= 24 && !avisado24) tier = '24';
  else if (horasRestantes <= 72 && !avisado72) tier = '72';

  if (!tier) continue;

  alertas.push({
    json: {
      dedup_key: fila.dedup_key,
      empresa: fila.empresa,
      puesto: fila.puesto,
      obligacion_tipo: fila.obligacion_tipo,
      obligacion_fecha: fila.obligacion_fecha,
      horas_restantes: Math.round(horasRestantes),
      tier,
      avisado_72h: horasRestantes <= 72 ? true : avisado72,
      avisado_24h: horasRestantes <= 24 ? true : avisado24,
      avisado_6h: horasRestantes <= 6 ? true : avisado6,
    },
  });
}

return alertas;

const items = $input.all().map((i) => i.json);

if (items.length === 0) {
  return []; // nada para avisar hoy, no se genera item -> no dispara el mail
}

items.sort((a, b) => a.horas_restantes - b.horas_restantes);

const fila = (o) => `
  <tr>
    <td>${o.puesto || '(sin puesto)'} — ${o.empresa || '(sin empresa)'}</td>
    <td>${o.obligacion_tipo || 'obligación'}</td>
    <td>faltan ~${o.horas_restantes}hs</td>
  </tr>`;

const html = `
  <div style="font-family: sans-serif; max-width: 600px;">
    <h2>⏰ Seguimiento de postulaciones</h2>
    <table cellpadding="6">${items.map(fila).join('')}</table>
  </div>`;

return [{
  json: {
    asunto: `Seguimiento — ${items.length} obligaci${items.length > 1 ? "ones" : "ón"} próxima${items.length > 1 ? 's' : ''}`,
    html,
  },
}];
